export function sbaseOf(p, bo, ao) {
    return (bo + AB_HDR) + (2 * p[ao + 1]);
}

export function ringOf(p, bo, ao, po) {
    return sbaseOf(p, bo, ao) + (AFW * p[po + 6]);
}

