    if (!charge(s, c16(aw), at)) {
        return -R_BUDGET;
    }
    if (tier === TIER_A1) {
        const rows = p[po + 4] + 1;
        const row = ringOf(p, bo, ao, po) + (aw * ((i % rows) | 0));
        for (let j = 0; j < aw; j++) {
            const v = s[act + j];
            s[row + j] = v;
        }
        return 0;
    }
    const stride = s[bo + AB_STRIDE];
    const er = s[bo + AB_RBASE] + (i * stride);
